create extension if not exists pgcrypto;
do $$ begin create type public.security_classification as enum ('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED','LEADERSHIP_RESTRICTED','ANNUAL_STATEMENT_SECRET','INTELLIGENCE_SECRET','LEGAL_PRIVILEGE'); exception when duplicate_object then null; end $$;
-- Identity, organisation, people and institutions
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, email text, is_active boolean not null default true, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.roles (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, description text, is_system boolean not null default false, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.permissions (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, domain text not null, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, role_id uuid not null references public.roles(id) on delete cascade, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,role_id));
create table if not exists public.role_permissions (id uuid primary key default gen_random_uuid(), role_id uuid not null references public.roles(id) on delete cascade, permission_id uuid not null references public.permissions(id) on delete cascade, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(role_id,permission_id));
create table if not exists public.data_scopes (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, scope_code text not null, scope_type text not null default 'organisation', active boolean not null default true, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,scope_code));
create table if not exists public.security_compartments (id uuid primary key default gen_random_uuid(), code public.security_classification not null unique, name text not null, description text, classification public.security_classification not null default 'RESTRICTED', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_compartments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, compartment_id uuid not null references public.security_compartments(id) on delete cascade, granted_by uuid references public.profiles(id), granted_at timestamptz not null default now(), classification public.security_classification not null default 'RESTRICTED', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,compartment_id));
create table if not exists public.divisions (id uuid primary key default gen_random_uuid(), name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.units (id uuid primary key default gen_random_uuid(), name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.teams (id uuid primary key default gen_random_uuid(), name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.positions (id uuid primary key default gen_random_uuid(), name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.officer_assignments (id uuid primary key default gen_random_uuid(), name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.people (id uuid primary key default gen_random_uuid(), full_name text not null, person_type text, contact_details jsonb not null default '{}'::jsonb, classification public.security_classification not null default 'CONFIDENTIAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.leaders (id uuid primary key default gen_random_uuid(), person_id uuid not null references public.people(id), leader_status text not null default 'active', classification public.security_classification not null default 'LEADERSHIP_RESTRICTED', organisation_scope text default 'leadership', case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.leader_positions (id uuid primary key default gen_random_uuid(), leader_id uuid references public.leaders(id), title text, classification public.security_classification not null default 'LEADERSHIP_RESTRICTED', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.government_bodies (id uuid primary key default gen_random_uuid(), name text not null, body_type text, province text, status text not null default 'active', classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.government_body_contacts (id uuid primary key default gen_random_uuid(), government_body_id uuid references public.government_bodies(id), contact_name text, classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.liaison_officers (id uuid primary key default gen_random_uuid(), government_body_id uuid references public.government_bodies(id), person_id uuid references public.people(id), classification public.security_classification not null default 'INTERNAL', organisation_scope text, case_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
